  this.scene.add(new THREE.HemisphereLight('#fff0d5','#526547',2));const key=new THREE.DirectionalLight('#fff6df',3);key.position.set(-100,130,100);this.scene.add(key);const rim=new THREE.DirectionalLight('#c4d9bf',2);rim.position.set(80,100,-100);this.scene.add(rim);
  this.root=new THREE.Group();this.scene.add(this.root);this.ray=new THREE.Raycaster();this.pointer=new THREE.Vector2();this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(host);this.resize();this.view('home');this.bind();this.renderer.setAnimationLoop(t=>this.frame(t));
