 async load(){const gltf=await new GLTFLoader().loadAsync(this.config.model,e=>this.events.onProgress(e.total?e.loaded/e.total:null));if(this.disposed){this.release(gltf.scene);return}gltf.scene.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(gltf.scene),s=b.getSize(new THREE.Vector3()),c=b.getCenter(new THREE.Vector3()),scale=100/Math.max(...s.toArray());this.objectHeight=s.y*scale;
  gltf.scene.traverse(original=>{if(!original.isMesh)return;const g=original.geometry.clone();g.applyMatrix4(original.matrixWorld);g.translate(-c.x,-b.min.y,-c.z);g.scale(scale,scale,scale);const p=g.attributes.position,idx=g.index,groups=new Map();for(let i=0;i<idx.count;i+=3){const a=idx.getX(i),b=idx.getX(i+1),c=idx.getX(i+2),name=surfacePart(this.id,(p.getX(a)+p.getX(b)+p.getX(c))/3,(p.getY(a)+p.getY(b)+p.getY(c))/3,(p.getZ(a)+p.getZ(b)+p.getZ(c))/3);if(!groups.has(name))groups.set(name,[]);groups.get(name).push(a,b,c)}
   for(const [name,indices] of groups){const group=new THREE.Group();group.name=name;this.parts.set(name,group);this.root.add(group);const geometry=new THREE.BufferGeometry();for(const [key,attr] of Object.entries(g.attributes))geometry.setAttribute(key,attr);geometry.setIndex(indices);geometry.computeBoundingSphere();const mat=original.material.clone();mat.metalness=.04;mat.metalnessMap=null;mat.roughnessMap=null;mat.roughness=.78;mat.envMapIntensity=.35;mat.side=THREE.DoubleSide;const mesh=new THREE.Mesh(geometry,mat);mesh.userData.part=name;group.add(mesh);this.pickables.push(mesh)}original.geometry.dispose();
  });
  if(this.id==='duck')this.makeDuck();if(this.id==='jz-458')this.makePig();if(this.id==='chest')this.makeStars();this.ready=true;this.events.onReady();
 }
 material(color){return new THREE.MeshStandardMaterial({color,roughness:.63,metalness:.07,side:THREE.DoubleSide})}
