 makeDuck(){this.headPivot=new THREE.Vector3(-29,43,0);const h=this.parts.get('head');h.children.forEach(m=>m.position.sub(this.headPivot));h.position.copy(this.headPivot);this.mesh(new THREE.CylinderGeometry(4.5,4.5,2,32),this.material('#4f3427'),[-29,43,0],this.root);this.mesh(new THREE.CylinderGeometry(2,2,9,24),this.material('#765039'),[0,-3,0],h);this.liner=this.makeTray(40,25,9,[8,36,0]);this.liner.visible=false;this.lidBase=this.mesh(new THREE.BoxGeometry(40,.7,25),this.material('#35251e'),[8,41,0],this.parts.get('lid'));this.lidBase.visible=false}
 makeTray(w,d,h,pos){const tray=new THREE.Group();tray.position.fromArray(pos);this.root.add(tray);const mat=this.material('#51251f');this.mesh(new THREE.BoxGeometry(w,1,d),mat,[0,-h/2,0],tray);for(const z of [-1,1])this.mesh(new THREE.BoxGeometry(w,h,.8),mat,[0,0,z*d/2],tray);for(const x of [-1,1])this.mesh(new THREE.BoxGeometry(.8,h,d),mat,[x*w/2,0,0],tray);return tray}
 makePig(){this.liner=this.makeTray(67,29,14,[0,15,0]);this.liner.visible=false;this.mesh(new THREE.CylinderGeometry(1,1,.7,64),this.material('#4d231d'),[0,22.4,0],this.parts.get('lid')).scale.set(43,1,17);this.cups=[];for(let i=0;i<3;i++){const cup=new THREE.Group();cup.userData.part='cup';cup.userData.index=i;this.root.add(cup);const points=[new THREE.Vector2(0,0),new THREE.Vector2(4,.3),new THREE.Vector2(6,2),new THREE.Vector2(7,4),new THREE.Vector2(6.3,4.2),new THREE.Vector2(5.2,2.1),new THREE.Vector2(3.6,.9),new THREE.Vector2(0,.8)];const bowl=this.mesh(new THREE.LatheGeometry(points,40),this.material('#a04f39'),[0,0,0],cup,'cup');bowl.scale.z=.6;bowl.userData.index=i;for(const x of [-1,1]){const ear=this.mesh(new THREE.SphereGeometry(2.4,16,10),this.material('#3a211b'),[x*7.3,3.3,0],cup,'cup');ear.scale.set(1,.18,.65);ear.userData.index=i}cup.position.copy(this.cupPosition(i,false));this.cups.push(cup)}}
 cupPosition(i,inside){return new THREE.Vector3((i-1)*22,inside?16.5:2,inside?0:40)}
 makeStars(){this.starGroup=new THREE.Group();this.starGroup.visible=false;this.root.add(this.starGroup);const ring=[];for(let i=0;i<=112;i++){const a=i/112*Math.PI*2;ring.push(new THREE.Vector3(Math.cos(a)*48,0,Math.sin(a)*48))}this.starGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ring),new THREE.LineBasicMaterial({color:'#8e896b',transparent:true,opacity:.55})));
  for(let j=0;j<4;j++){const a=j*Math.PI/2;const label={name:seasons[j].direction+' · '+seasons[j].name,p:new THREE.Vector3(Math.cos(a)*70,0,Math.sin(a)*70),kind:'direction'};this.labels.push(label);for(let k=0;k<7;k++){const ang=a+(k-3)*.19,point=new THREE.Vector3(Math.cos(ang)*48,0,Math.sin(ang)*48);this.mesh(new THREE.SphereGeometry(.75,12,8),new THREE.MeshBasicMaterial({color:seasons[j].color}),point.toArray(),this.starGroup);this.labels.push({name:mansionGroups[j][k],p:point.clone().multiplyScalar(1.09),kind:'mansion'})}}
  this.dipper=new THREE.Group();this.starGroup.add(this.dipper);const points=[[-23,0,-8],[-24,0,7],[-11,0,10],[-9,0,-2],[2,0,0],[12,0,0],[25,0,0]],vectors=points.map(p=>new THREE.Vector3(...p));const bowl=[...vectors.slice(0,4),vectors[0],vectors[3],...vectors.slice(4)];this.dipper.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(bowl),new THREE.LineBasicMaterial({color:'#ddc286'})));for(const p of points){const star=this.mesh(new THREE.SphereGeometry(1.4,18,12),new THREE.MeshBasicMaterial({color:'#ffe6a6'}),p,this.dipper,'handle');star.userData.handle=true}this.handle=this.mesh(new THREE.SphereGeometry(3.4,16,12),new THREE.MeshBasicMaterial({color:'#e4bd77',transparent:true,opacity:.5}),[25,0,0],this.dipper,'handle');
 }
 setState(state){this.state=state;if(this.id==='jz-458'&&state.lid>.7&&!this.wasLid)this.view('open');this.wasLid=state.lid>.7;if(this.id==='chest'&&state.stars&&!this.wasStars){this.view('stars')}this.wasStars=state.stars}
