 hit(e){const r=this.canvas.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2);this.ray.setFromCamera(this.pointer,this.camera);return this.ray.intersectObjects(this.pickables).find(h=>h.object.visible&&(h.object.userData.part!=='handle'||this.starGroup?.visible))}
 pointerPlane(e,y){this.hit(e);return this.ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),-y),new THREE.Vector3())}
 bind(){let down=null;const signal=this.abort.signal;
  this.canvas.addEventListener('pointerdown',e=>{if(e.button!==0||!this.ready)return;const hit=this.hit(e),part=hit?.object.userData.part;down={x:e.clientX,y:e.clientY,id:e.pointerId,part,index:hit?.object.userData.index,head:this.state.head,angle:this.state.angle,moved:false};if(['head','cup','handle'].includes(part)){e.stopImmediatePropagation();this.controls.enabled=false;this.canvas.setPointerCapture(e.pointerId)}},{capture:true,signal});
  this.canvas.addEventListener('pointermove',e=>{if(!down||e.pointerId!==down.id)return;down.moved||=Math.hypot(e.clientX-down.x,e.clientY-down.y)>5;if(!down.moved)return;if(down.part==='head')this.events.onAction({type:'head',value:down.head+(e.clientX-down.x)*.7});if(down.part==='handle'){const p=this.pointerPlane(e,this.starGroup.position.y);if(p)this.events.onAction({type:'angle',value:Math.atan2(p.z,p.x)*180/Math.PI})}if(down.part==='cup'&&this.state.lid>.7){const p=this.pointerPlane(e,24);if(p){this.dragCup=down.index;this.cups[down.index].position.copy(p);this.cups[down.index].position.y=27}}},{signal});
  const end=(e,cancel=false)=>{if(!down||e.pointerId!==down.id)return;const d=down;down=null;this.controls.enabled=true;if(this.canvas.hasPointerCapture(e.pointerId))this.canvas.releasePointerCapture(e.pointerId);if(cancel){this.dragCup=null;return}if(this.dragCup!==null&&this.dragCup!==undefined){const p=this.cups[this.dragCup].position;this.events.onAction({type:'cup',index:this.dragCup,inside:Math.abs(p.x)<40&&Math.abs(p.z)<22});this.dragCup=null}else if(!d.moved){if(d.part==='head')this.events.onAction({type:'head',value:this.state.head>=130?-140:this.state.head+45});else if(d.part==='lid')this.events.onAction({type:this.id==='chest'?'stars':'lid',value:this.id==='chest'?!this.state.stars:1-this.state.lid});else if(d.part==='cup')this.events.onAction({type:'cup',index:d.index,inside:!this.state.cups[d.index]});if(d.part)this.events.onPart(d.part==='cup'?'cup':d.part==='handle'?'season':d.part)}};
  this.canvas.addEventListener('pointerup',e=>end(e),{signal});this.canvas.addEventListener('pointercancel',e=>end(e,true),{signal});this.canvas.addEventListener('lostpointercapture',e=>{if(down)end(e,true)},{signal});window.addEventListener('blur',()=>{down=null;this.dragCup=null;this.controls.enabled=true},{signal});
  this.canvas.addEventListener('wheel',e=>e.preventDefault(),{passive:false,signal});this.canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();this.events.onError('三维显示已暂停，请刷新恢复。')},{signal});this.canvas.addEventListener('keydown',e=>{if(e.key==='Home'){e.preventDefault();this.view('home')}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key)){e.preventDefault();const offset=this.camera.position.clone().sub(this.controls.target),s=new THREE.Spherical().setFromVector3(offset);s.theta+=e.key==='ArrowLeft'?.12:e.key==='ArrowRight'?-.12:0;s.phi+=e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0;if(e.key==='+')s.radius*=.85;if(e.key==='-')s.radius*=1.15;s.radius=Math.max(70,Math.min(370,s.radius));s.makeSafe();this.camera.position.copy(this.controls.target).add(offset.setFromSpherical(s))}},{signal});
 }
 screen(p){const q=p.clone().project(this.camera);return {x:(q.x+1)*this.width/2,y:(1-q.y)*this.height/2,visible:q.z>-1&&q.z<1&&Math.abs(q.x)<1&&Math.abs(q.y)<1}}
 anchor(part){if(this.id==='duck')return new THREE.Vector3(...(part==='head'?[-29,64,0]:[8+this.lift*14,48+this.lift*29,0]));if(this.id==='jz-458')return new THREE.Vector3(0,45+this.lift*38,-this.lift*12);return new THREE.Vector3(0,this.state.stars?this.starGroup?.position.y||90:57,0)}
 frame(now){if(this.disposed)return;const dt=Math.min(.05,(now-(this.last||now))/1000);this.last=now;const k=this.reduced?1:Math.min(1,dt*8);this.controls.update();if(this.ready){this.lift+=(this.state.lid-this.lift)*k;this.headAngle+=(this.state.head-this.headAngle)*k;const lid=this.parts.get('lid');if(this.id==='duck'){this.parts.get('head').rotation.y=this.headAngle*Math.PI/180;lid.position.set(this.lift*14,this.lift*29,0);this.liner.visible=this.lift>.05;this.lidBase.visible=this.lift>.05}else if(this.id==='jz-458'){lid.position.set(0,this.lift*38,-this.lift*12);this.liner.visible=this.lift>.05;this.cups.forEach((c,i)=>{if(this.dragCup!==i)c.position.lerp(this.cupPosition(i,this.state.cups[i]),k)})}else{this.starAmount+=((this.state.stars?1:0)-this.starAmount)*k;this.starGroup.visible=this.starAmount>.015;this.starGroup.position.y=52+this.starAmount*43;this.starGroup.scale.setScalar(.35+.65*this.starAmount);this.dipper.rotation.y=-this.state.angle*Math.PI/180;const color=seasons[seasonAt(this.state.angle)].color;this.dipper.children.forEach(m=>m.material.color.set(color))}this.events.onFrame()}
  this.renderer.render(this.scene,this.camera);
 }
 release(root){const g=new Set(),m=new Set(),t=new Set();root.traverse(o=>{if(o.geometry)g.add(o.geometry);if(o.material){for(const mat of Array.isArray(o.material)?o.material:[o.material]){m.add(mat);for(const v of Object.values(mat))if(v?.isTexture)t.add(v)}}});g.forEach(o=>o.dispose());m.forEach(o=>o.dispose());t.forEach(o=>o.dispose())}
 suspend(){this.renderer.setAnimationLoop(null)}resume(){if(!this.disposed&&!document.hidden){this.last=0;this.renderer.setAnimationLoop(t=>this.frame(t))}}dispose(){this.disposed=true;this.suspend();this.abort.abort();this.controls.dispose();this.resizeObserver.disconnect();this.release(this.root);this.environment.dispose();this.pmrem.dispose();this.renderer.dispose()}
